import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt(), m = r.nextInt();
        int[] jobs = new int[n];
        for (int i = 0; i < n; i++) jobs[i] = r.nextInt();
        long[] sh = new long[m + 1], lo = new long[m + 1];
        for (int i = 1; i <= m; i++) sh[i] = r.nextLong();
        for (int i = 1; i <= m; i++) lo[i] = r.nextLong();
        final long INF = Long.MAX_VALUE / 4;
        // dp[j] + offset: best cost when the active processor last ran p and the other last ran j (0 = unused).
        long[] dp = new long[m + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        long firstV = 0, secondV = INF;
        int firstI = 0, secondI = -1;
        long offset = 0;
        int p = 0;
        for (int t : jobs) {
            long without = firstI != t ? firstV : secondV;
            long sw = offset + Math.min(dp[t] + sh[t], without + lo[t]);
            offset += p == t ? sh[t] : lo[t];
            long value = sw - offset;
            if (value < dp[p]) {
                dp[p] = value;
                // Keep the two smallest (value, index) entries at distinct indices.
                if (firstI == p) { firstV = value; }
                else if (secondI == p) {
                    secondV = value;
                    if (secondV < firstV || (secondV == firstV && secondI < firstI)) {
                        long tv = firstV; firstV = secondV; secondV = tv;
                        int ti = firstI; firstI = secondI; secondI = ti;
                    }
                } else if (value < firstV || (value == firstV && p < firstI)) {
                    secondV = firstV; secondI = firstI; firstV = value; firstI = p;
                } else if (value < secondV || (value == secondV && p < secondI)) {
                    secondV = value; secondI = p;
                }
            }
            p = t;
        }
        System.out.println(firstV + offset);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

