type entry struct{ v, i int }

func less(a, b entry) bool { return a.v < b.v || (a.v == b.v && a.i < b.i) }

func main() {
	n, m := readInt(), readInt()
	jobs := make([]int, n)
	for i := range jobs {
		jobs[i] = readInt()
	}
	sh := make([]int, m+1)
	lo := make([]int, m+1)
	for i := 1; i <= m; i++ {
		sh[i] = readInt()
	}
	for i := 1; i <= m; i++ {
		lo[i] = readInt()
	}
	const inf = 1 << 61
	// dp[j] + offset: best cost when the active processor last ran p and the other last ran j (0 = unused).
	dp := make([]int, m+1)
	for i := range dp {
		dp[i] = inf
	}
	dp[0] = 0
	first, second := entry{0, 0}, entry{inf, -1}
	offset, p := 0, 0
	for _, t := range jobs {
		without := first.v
		if first.i == t {
			without = second.v
		}
		sw := offset + min(dp[t]+sh[t], without+lo[t])
		if p == t {
			offset += sh[t]
		} else {
			offset += lo[t]
		}
		value := sw - offset
		if value < dp[p] {
			dp[p] = value
			e := entry{value, p}
			// Keep the two smallest entries at distinct indices.
			if first.i == p {
				first = e
			} else if second.i == p {
				second = e
				if less(second, first) {
					first, second = second, first
				}
			} else if less(e, first) {
				second, first = first, e
			} else if less(e, second) {
				second = e
			}
		}
		p = t
	}
	fmt.Println(first.v + offset)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
